5. le test pytest qui prouvera la nouvelle règle.
Ma prévision : <tables touchées, sens et ordre de grandeur>. Compare.

def texte_vers_millimes(texte) -> int:
    """« 18,500 », « 18.5 », « 1 240,000 » → millimes entiers."""
    t = str(texte).strip().replace(" ", "").replace(",", ".")
    if not re.fullmatch(r"\d+(\.\d+)?", t):
        raise ValueError(f"montant illisible {texte!r}")
    entier, _, dec = t.partition(".")
    return int(entier) * 1000 + int((dec + "000")[:3])
